# perl -I ./ LvCorporaTools/OneOffs/TagAuxCopBuut.pm data

# IDs were obtained by following TrEd querry:
# a-xinfo
# [ tag ~ '\\[(act|pass)',
#       a-node $child :=
#      [ m/tag ~ '^vb' ] ];
#   >> for $child.m/id give $1 sort by $1 asc
