my $source = shift @ARGV;
my $dest = (shift @ARGV or "$source/res");

my $processM = sub {
    LvCorporaTools::PMLUtils::TagChangeUtils::change_m_tag($_[0], $_[1], '^vb', 'va', \@M_NODES_TO_VA);
    LvCorporaTools::PMLUtils::TagChangeUtils::change_m_tag($_[0], $_[1], '^vb', 'vc', \@M_NODES_TO_VC);
};

my $processA = sub {
    LvCorporaTools::PMLUtils::TagChangeUtils::change_a_tags($_[0], $_[1], '^vb', 'va', \@A_NODES_TO_VA);
    LvCorporaTools::PMLUtils::TagChangeUtils::change_a_tags($_[0], $_[1], '^vb', 'vc', \@A_NODES_TO_VC);
};

my $procFileM = sub
{
    LvCorporaTools::GenericUtils::UIWrapper::transformMFile(
        0, $processM, 0, 0, '', @_);
};

my $procFileA = sub
{
    LvCorporaTools::GenericUtils::UIWrapper::transformAFile(
        $processA, 0, 0, '', '', @_);
};
print "==== Processing M files. =====================================\n";
LvCorporaTools::GenericUtils::UIWrapper::processDir($procFileM, "^.+\\.m\$", '.m', 1, 0, $source);
print "==== Processing A files. =====================================\n";
LvCorporaTools::GenericUtils::UIWrapper::processDir($procFileA, "^.+\\.a\$", '.a', 1, 0, $source);

if ("$source/res" ne $dest)
{
    File::Copy::move("$source/res", $dest)
        || warn "Moving $source/res to $dest failed: $!";
}

my @files = glob("$source/*.w");
File::Copy::copy($_, $dest) for (@files);
print "==== Done. ===================================================\n";

